def klasse(z):
    if z in "+-":
        return "vz"
    if z in "0123456789":
        return "ziffer"
    return "sonst"

delta = {
    "START": {"vz": "VZ",
              "ziffer": "ZAHL"},
    "VZ":    {"ziffer": "ZAHL"},
    "ZAHL":  {"ziffer": "ZAHL"},
}
ENDE = {"ZAHL"}

def akzeptiert(wort):
    zustand = "START"
    for z in wort:
        zeile = delta[zustand]
        k = klasse(z)
        if k not in zeile:
            return False  # Fehler
        zustand = zeile[k]
    return zustand in ENDE

for w in ["42", "-7", "+", "4-2"]:
    print(w, akzeptiert(w))

# 42 True
# -7 True
# + False
# 4-2 False

// Zustände: 0=Start 1=Vz 2=Zahl 3=Fehler
// Spalten:  vz, ziffer, sonst
int[,] delta =
{
    { 1, 2, 3 },   // 0 Start
    { 3, 2, 3 },   // 1 Vz
    { 3, 2, 3 },   // 2 Zahl
    { 3, 3, 3 },   // 3 Fehler
};

int Klasse(char c) =>
    c is '+' or '-' ? 0
    : char.IsAsciiDigit(c) ? 1
    : 2;

bool Akzeptiert(string wort)
{
    int z = 0;
    foreach (char c in wort)
        z = delta[z, Klasse(c)];
    return z == 2;
}

string[] tests = ["42", "-7", "+", "4-2"];
foreach (var w in tests)
{
    bool ok = Akzeptiert(w);
    Console.WriteLine($"{w}: {ok}");
}

// 42: True
// -7: True
// +: False
// 4-2: False

